import { useEffect, useState } from "react";
import { SANIDADE_MAXIMA, useAgente } from "../../context/agenteContext.js";
import "./home.css";

const DANIEL_FOTO_1 = "data:image/png;base64,";
const DANIEL_FOTO_2 = "data:image/png;base64,";
const DIARIO_FOTO = "data:image/png;base64,";
const RITUAL_FOTO = "data:image/png;base64,";

// ---------------------------------------------------------------------------
// ARQUIVOS H4RTM4NND4N13L — Home (só para agentes logados)
//
// As fotos ficam veladas. Cada vez que o agente abre uma delas, perde
// sanidade (o custo de cada foto está em FOTOS). Quanto menor a sanidade,
// mais embaçado e distorcido o site fica.
// ---------------------------------------------------------------------------

const wobble = (i) => {
  const rot = ((i * 37) % 13) - 6; // -6deg a 6deg
  const ty = ((i * 53) % 9) - 4; // -4px a 4px
  return `rotate(${rot}deg) translateY(${ty}px)`;
};

const TITLE_LINES = ["ARQUIVOS", "H4RTM4NND4N13L"];

// custo = quanto de sanidade o agente perde ao olhar a foto
const FOTOS = {
  daniel1: { label: "Daniel Hartmann", src: DANIEL_FOTO_1, custo: 2, tapeColor: "#c9a13f" },
  daniel2: { label: "Daniel Hartmann", src: DANIEL_FOTO_2, custo: 2, tapeColor: "#34526b" },
  diario: { label: "Diário de Daniel Hartmann", src: DIARIO_FOTO, custo: 3, tapeColor: "#6b3f77" },
  ritual: { label: "Ritual de Daniel Hartmann", src: RITUAL_FOTO, custo: 5, tapeColor: "#a3392f" },
};

// Efeitos visuais conforme a sanidade perdida (0 = nada perdido, 20 = tudo)
function efeitoSanidade(sanidade) {
  const perdida = SANIDADE_MAXIMA - sanidade;
  const blur = (perdida / SANIDADE_MAXIMA) * 5; // até 5px
  const saturacao = 1 - (perdida / SANIDADE_MAXIMA) * 0.6;
  const matiz = perdida > 10 ? (perdida - 10) * 6 : 0; // cores "erradas" só depois da metade
  return {
    filter: `blur(${blur.toFixed(2)}px) saturate(${saturacao.toFixed(2)}) hue-rotate(${matiz}deg)`,
  };
}

function nivelSanidade(sanidade) {
  if (sanidade <= 5) return "delirando";
  if (sanidade <= 10) return "perturbado";
  if (sanidade <= 15) return "inquieto";
  return "estavel";
}

const DANIEL_TEXT = [
  `Meu nome é Daniel Hartmann, e se esses arquivos vazaram, significa que algo saiu do caminho e que eu não estou mais no controle. Não recomendo que continue a explorar os arquivos, pois até mesmo eu tenho constantes dores de cabeça e certas alucinações quando edito ou anoto algumas informações aqui. Tome cuidado para não ser o próximo, sua sanidade mental sempre deve estar em primeiro lugar!`,
  `Sou escritor de contos macabros e relatos sobrenaturais de muito sucesso, mas o que eu não sabia — até entrar na Ordem — era que o medo causado pelas minhas obras enfraquecia a Membrana. Na primeira vez em que me envolvi em uma investigação paranormal da Ordem, fui confrontado por um homem que se chamava Tristan Monteiro. Foi assim que descobri o que eu realmente fazia ao postar minhas obras, meus contos, meus livros.`,
  `Há muito mais o que eu poderia falar, mas para proteger a Membrana, a minha e a sua sanidade, irei finalizar por aqui, será mais seguro assim. Decidi trabalhar na organização para combater o paranormal e minhas próprias monstruosas criações.`,
];

const CASE_FILES = [
  {
    quote:
      "Daniel Hartmann foi morto pela Degolificada durante a varredura no bunker da Escola Nostradamus de Ensino Médio em São Paulo, sendo devorado ao meio pela criatura.",
    editor: "WEBBER, Elizabeth",
    year: "2020",
  },
  {
    quote:
      "Os Arquivos de Daniel Hartmann serão expostos para que Agentes do mundo todo tenham noção do que lidamos todos os dias. A Membrana e o Outro Lado são brutais.",
    editor: "VERÍSSIMO",
    year: "2025",
  },
  {
    quote:
      "A Ordo Realitas foi criada para que pessoas que nunca tiveram exposição ao paranormal evitem de ter esse contato algum dia. O Apocalipse está próximo.",
    editor: "CERVERO, Arthur",
    year: "2026",
  },
];

// Foto velada: só dá para ver de verdade clicando (e pagando sanidade)
function PhotoFrame({ foto, tall, onAbrir }) {
  return (
    <button
      type="button"
      className={`photo-frame photo-frame--velada${tall ? " photo-frame--tall" : ""}`}
      onClick={onAbrir}
      aria-label={`Ver ${foto.label} (custa ${foto.custo} de sanidade)`}
    >
      <img className="photo-frame__img" src={foto.src} alt="" />
      <span className="photo-frame__aviso">
        <span>{foto.label}</span>
        <span>clique para ver &mdash; &minus;{foto.custo} SAN</span>
      </span>
      <span
        className="photo-frame__tape"
        style={{ background: foto.tapeColor, opacity: 0.85 }}
        aria-hidden="true"
      />
    </button>
  );
}

export default function ArquivosHartmann() {
  const { agente, perderSanidade, sair } = useAgente();
  const [fotoAberta, setFotoAberta] = useState(null);

  const sanidade = agente.sanidade ?? SANIDADE_MAXIMA;
  const enlouqueceu = sanidade <= 0;

  function abrirFoto(id) {
    setFotoAberta(id);
    perderSanidade(FOTOS[id].custo);
  }

  // Esc fecha a foto
  useEffect(() => {
    if (!fotoAberta) return;
    const aoTeclar = (e) => e.key === "Escape" && setFotoAberta(null);
    window.addEventListener("keydown", aoTeclar);
    return () => window.removeEventListener("keydown", aoTeclar);
  }, [fotoAberta]);

  return (
    <>
      <div
        className={`ah-root sn-conteudo sn-conteudo--${nivelSanidade(sanidade)}`}
        style={efeitoSanidade(sanidade)}
      >
        <div className="ah-classification-bar" aria-hidden="true">
          <span className="ah-classification-bar__seg ah-classification-bar__seg--black" />
          <span className="ah-classification-bar__seg ah-classification-bar__seg--yellow" />
          <span className="ah-classification-bar__seg ah-classification-bar__seg--red" />
          <span className="ah-classification-bar__seg ah-classification-bar__seg--purple" />
          <span className="ah-classification-bar__seg ah-classification-bar__seg--blue" />
        </div>

        {/* Título */}
        <header className="ah-title">
          {TITLE_LINES.map((line, li) => (
            <span className="ah-title__line" key={li}>
              {line.split("").map((ch, i) => (
                <span
                  className="ah-title__letter"
                  key={i}
                  style={{ transform: wobble(li * 20 + i) }}
                >
                  {ch === " " ? "\u00A0" : ch}
                </span>
              ))}
            </span>
          ))}
          <span className="ah-title__sub">arquivo pessoal &mdash; acesso não autorizado</span>
        </header>

        <div className="ah-container">
          {/* Foto + texto do Daniel */}
          <section className="ah-section ah-daniel">
            <div className="ah-row">
              <PhotoFrame foto={FOTOS.daniel1} tall onAbrir={() => abrirFoto("daniel1")} />
              <div>
                {DANIEL_TEXT.map((p, i) => (
                  <p key={i}>{p}</p>
                ))}
              </div>
            </div>
          </section>

          {/* Segunda foto + diário */}
          <section className="ah-section">
            <div className="ah-row ah-row--photos">
              <PhotoFrame foto={FOTOS.daniel2} tall onAbrir={() => abrirFoto("daniel2")} />
              <PhotoFrame foto={FOTOS.diario} tall onAbrir={() => abrirFoto("diario")} />
            </div>
          </section>

          {/* Anotações dos agentes */}
          <section className="ah-section">
            <p className="ah-casefiles-heading">registro pós-óbito &mdash; editado por agentes da ordem</p>
            {CASE_FILES.map((cf, i) => (
              <div
                className={`ah-casefile${i === 1 ? " ah-casefile--purple" : ""}${i === 2 ? " ah-casefile--blue" : ""}`}
                key={i}
              >
                <p className="ah-casefile__quote">&ldquo;{cf.quote}&rdquo;</p>
                <div className="ah-casefile__editor">
                  <span>--- Editado por: {cf.editor}</span>
                  <span>{cf.year}</span>
                </div>
              </div>
            ))}
          </section>

          {/* Ritual */}
          <section className="ah-section ah-ritual">
            <PhotoFrame foto={FOTOS.ritual} onAbrir={() => abrirFoto("ritual")} />
            <p className="ah-ritual__caption">último registro visual recuperado</p>
          </section>
        </div>
      </div>

      {/* Foto aberta (fica fora do conteúdo embaçado) */}
      {fotoAberta && !enlouqueceu && (
        <div className="sn-lightbox" role="dialog" aria-label={FOTOS[fotoAberta].label} onClick={() => setFotoAberta(null)}>
          <figure className="sn-lightbox__figura" onClick={(e) => e.stopPropagation()}>
            <img src={FOTOS[fotoAberta].src} alt={FOTOS[fotoAberta].label} />
            <figcaption>
              {FOTOS[fotoAberta].label} &mdash; você perdeu {FOTOS[fotoAberta].custo} de sanidade
            </figcaption>
          </figure>
          <button type="button" className="sn-lightbox__fechar" onClick={() => setFotoAberta(null)}>
            fechar
          </button>
        </div>
      )}

      {enlouqueceu && (
        <div className="sn-loucura" role="alertdialog" aria-label="Sanidade esgotada">
          <p className="sn-loucura__titulo">SANIDADE ESGOTADA</p>
          <p>
            {agente.nome}, você viu demais. A Membrana cedeu dentro da sua cabeça e os arquivos
            já não fazem sentido.
          </p>
          <button type="button" className="sn-loucura__botao" onClick={sair}>
            abandonar os arquivos
          </button>
        </div>
      )}
    </>
  );
}
